import React from 'react';
import './timelineIcon.css';

function Icon({ type }) {

  try {
    require(`../../../assets/img/icons/${type}.svg`)
    return (
      <img 
        src={require(`../../../assets/img/icons/${type}.svg`)} 
        alt="icon" 
        style={{ width: '80%', height: '80%' }} 
      />
    );
  } catch (_) {
    return (
      <img 
        src={require(`../../../assets/img/icons/Update.svg`)} 
        alt="icon" 
        style={{ width: '80%', height: '80%' }} 
      />
    );
  }

}

export default Icon;
