import React, { useState, useEffect, useContext, useMemo, useRef } from "react";
import { Card, Button, Col, Row } from "@themesberg/react-bootstrap";
import { securedAxiosInstance } from "../../../axiosConfig";
import Loader from "../../../components/Loader";
import "./showNotifications.css";
import { AuthContext } from "../../../context/AuthContext";
import { Announcement, filtersType, NoticeThread } from "../../../types/notice";
import { AxiosResponse } from "axios";
import NoticeThreadUI from "./NoticeThread";

// Registering service worker for notification
// Public Vapid key for notification
const publicVapidKey=
  "BELqxt1OA-x3CSPf2TMWA5vdZAljkYU3oNeQfY5SmT5uZm0N1LxGv_s6SU_O26z4nDQAtbCq4N-TZgbXyaOqb2M";

// Encryption of public VAPID key
function urlB64ToUint8Array(base64String: string) {
  var padding="=".repeat((4-(base64String.length%4))%4);
  var base64=(base64String+padding).replace(/\-/g, "+").replace(/_/g, "/");

  var rawData=window.atob(base64);
  var outputArray=new Uint8Array(rawData.length);

  for (var i=0; i<rawData.length; ++i) {
    outputArray[i]=rawData.charCodeAt(i);
  }
  return outputArray;
}
// Sending endpoints to store in database
async function saveSubscription(subscription: any, year: any, studentID: any, degree: any) {
  const response=await securedAxiosInstance.post(`/notifications`, {
    Batch: year,
    notify: subscription,
    student: studentID,
    degree: degree,
  });
}
/*******************************************************************************/

const ShowNotifications=({ activeFilter, selectedTag, searchQuery }: { activeFilter: filtersType, selectedTag: string | undefined, searchQuery: string | undefined }) => {
  const {
    state: { profileData },
  }=useContext(AuthContext);
  const degree=profileData?.degree;
  const batch=profileData?.batch;
  const studentID=profileData?.id;
  const placementBatch=profileData?.allowed_in_next_season === false ? batch : (Number(batch)+1).toString();


  useEffect(() => {
    const registerServiceWorker=async () => {
      if (!("serviceWorker" in navigator)) {
        // toast.error("Service Worker is not supported in your browser.");
        return;
      }

      if (!("PushManager" in window)) {
        // toast.error("Push notifications are not supported in your browser.");
        return;
      }

      try {
        // Register the service worker
        const swRegistration=await navigator.serviceWorker.register(
          "./service-worker.js",
          { scope: "/" }
        );

        // Check if the user is already subscribed
        const subscription=await swRegistration.pushManager.getSubscription();
        let isSubscribed=!(subscription===null);

        if (isSubscribed) {
          console.log("User is already subscribed.");
        } else {
          // Subscribe the user
          const newSubscription=await swRegistration.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: urlB64ToUint8Array(publicVapidKey),
          });

          // console.log("User is subscribed");
          saveSubscription(newSubscription, placementBatch, studentID, degree);
          isSubscribed=true;
        }
      } catch (error) {
        console.error(
          "Failed to register Service Worker or subscribe user:",
          error
        );
      }
    };

    registerServiceWorker();
  }, [publicVapidKey, batch, placementBatch]);

  const [notifications, setNotifications]=useState<{
    loading: boolean;
    data: Announcement[];
    error: any;
  }>({
    loading: false,
    data: [],
    error: null as any,
  });
  const [showMoreButton, setShowMoreButton]=useState(true);
  const [previousActiveFilter, setPreviousActiveFilter] = useState(activeFilter);
  const [previousSelectedTag, setPreviousSelectedTag] = useState(selectedTag);

  const start = useRef(0);

  useEffect(() => {
    start.current = 0;
    setShowMoreButton(true);
    fetchNotifications();
  }, [activeFilter, selectedTag, searchQuery]);

  const fetchNotifications=async () => {
    setNotifications({ ...notifications, loading: true });
    try {
      const response: AxiosResponse<Announcement[]> = await securedAxiosInstance.get(
        `/announcements?_sort=createdAt:desc&_where[batches_contains]=${placementBatch}&_where[degrees_contains]=${degree}&_start=${start.current}&_limit=12${activeFilter === "All" ? "" : `&type=${activeFilter}`}${!selectedTag ? "" : `&tag=${selectedTag}`}${!searchQuery ? "" : `&_where[_or][0][title_contains]=${searchQuery}&_where[_or][1][content_contains]=${searchQuery}&_where[_or][2][company_contains]=${searchQuery}`}`
      );
      const newData = response.data;

      const oldData = notifications.data;
      newData.forEach((item) => oldData.push(item));

      if (newData.length < 12) {
        setShowMoreButton(false);
      }

      if (previousActiveFilter !== activeFilter || previousSelectedTag !== selectedTag) {
        setPreviousSelectedTag(selectedTag);
        setPreviousActiveFilter(activeFilter);
        setNotifications({data: newData, loading: false, error: null});
      } else {
        setNotifications({ loading: false, data: oldData, error: null });
      }
      start.current += 12;
    } catch (error) {
      setNotifications({ loading: false, data: [], error: error });
      console.log(error);
    }
  };

  if (notifications.loading) {
    return <Loader />;
  }

  if (notifications.error) {
    return (
      <div>
        <h1>Error in fetching notifications.</h1>
      </div>
    );
  }

  if (notifications.data.length === 0) {
    return (
      <div className="d-flex flex-column align-items-center justify-content-center" style={{ minHeight: "40vh" }}>
        <img
          src={require("../../../assets/img/illustrations/notice.png")}
          alt="No Announcements"
          style={{ width: 90, height: 90, opacity: 0.7, marginBottom: 16 }}
        />
        <p style={{ color: "#aaa", fontSize: "1.05em", textAlign: "center" }}>
          You're all caught up!<br />Check back later for new updates.
        </p>
      </div>
    );
  }


  return (
    <div>
      <NoticeThreadUI notifications={notifications.data} fetchNotifications={fetchNotifications} showMoreButton={showMoreButton} />
    </div>
  );
};

export default ShowNotifications;