import { Badge } from "@themesberg/react-bootstrap";
import React from "react";
import { NoticeType } from "../../../types/notice";


function tagBadgeColor(type: string) : {
    icon: string;
    color: string;
    backgroundColor: string;
} {
  switch (type.toLowerCase()) {
    case "placement":
      return {
        icon: "fas fa-briefcase",
        color: "#0f5132", // Dark green
        backgroundColor: "#d1e7dd", // Light green
      };
    case "internship":
      return {
        icon: "fas fa-user-tie",
        color: "#084298", // Dark blue
        backgroundColor: "#cfe2ff", // Light blue
      };
    case "shortlist":
      return {
        icon: "fas fa-check",
        color: "#cc5500", // Dark orange
        backgroundColor: "#ffe5cc", // Light orange
      };
    case "update":
      return {
        icon: "fas fa-sync-alt",
        color: "#432874", // Dark purple
        backgroundColor: "#e0cffc", // Light purple
      };
    case "fte":
      return {
        icon: "fas fa-handshake",
        color: "#052c65", // Dark blue
        backgroundColor: "#cce7ff", // Light blue
      };
    case "internship+fte":
      return {
        icon: "fas fa-users",
        color: "#0a6847", // Dark teal
        backgroundColor: "#ccf2e8", // Light teal
      };
    case "internship+ppo":
      return {
        icon: "fas fa-star",
        color: "#3d0a91", // Dark indigo
        backgroundColor: "#d6ccff", // Light indigo
      };
    case "event":
      return {
        icon: "fas fa-calendar-day",
        color: "#212529", // Dark gray
        backgroundColor: "#f8f9fa", // Light gray
      };
    default:
      return {
        icon: "fas fa-bell",
        color: "#343a40", // Dark gray
        backgroundColor: "#f1f3f4", // Light gray
      };
  }
}

function typeBadgeColor(type: NoticeType) : {
  icon: string;
  color: string;
  backgroundColor: string;
} {
  switch (type) {
    case "CompanyEvent":
      return {  
        icon: "fas fa-calendar-day",
        color: "#0056b3", // More visible blue
        backgroundColor: "#e3eefd", // Slightly darker light blue
      };
    case "General":
      return {  
        icon: "fas fa-info-circle",
        color: "#495057", // Dark gray
        backgroundColor: "#e9ecef", // Light gray
      };
    default:
      return {
        icon: "fas fa-bell",
        color: "#343a40", // Dark gray
        backgroundColor: "#f1f3f4", // Light gray
      };
  }
}

function AnnouncementTagBadge({ type }: { type: string }) {
  const badgeStyles = tagBadgeColor(type);
  return (
    <Badge
      className="badge-md"
      style={{
        backgroundColor: badgeStyles.backgroundColor,
        display: "flex",
        alignItems: "center",
        gap: "0.5rem",
        padding: "0.5rem 1rem",
      }}
    >
      <i className={badgeStyles.icon} style={{ color: badgeStyles.color }}></i>
      <span style={{ fontSize: "0.9rem", color: badgeStyles.color }}>{type}</span>
    </Badge>
  );
}

export function AnnouncementTypeBadge({ type }: { type: NoticeType }) {
  const badgeStyles = typeBadgeColor(type);
  return (
    <Badge className="badge-md" style={{ backgroundColor: badgeStyles.backgroundColor, display: "flex", alignItems: "center", gap: "0.5rem", padding: "0.5rem 1rem" }}>
      <i className={badgeStyles.icon} style={{ color: badgeStyles.color }}></i>
      <span style={{ fontSize: "0.9rem", color: badgeStyles.color }}>{
        type === "CompanyEvent" ? "Company Event" : "General"
      }</span>
    </Badge>
  );
}

export default AnnouncementTagBadge;