import React, { useMemo } from "react";
import { Announcement, NoticeType } from "../../../types/notice";
import {
  VerticalTimeline,
  VerticalTimelineElement,
} from "react-vertical-timeline-component";
import "react-vertical-timeline-component/style.min.css";
import { Card, Button, Col, Row } from "@themesberg/react-bootstrap";
import HtmlText from "../../../components/HtmlToText/HtmlText";
import Icon from "./timelineIcon";
import { useNavigate } from "react-router-dom";
import "./showNotifications.css";
import AnnouncementTagBadge from "./AnnouncementTypeBadge";
import Loader from "../../../components/Loader";
import "./NoticeThread.css";

function NoticeThreadUI({notifications, fetchNotifications, showMoreButton}: {notifications: Announcement[], fetchNotifications: any, showMoreButton: any}) {
  const navigate = useNavigate();

    const bgColor: Record<NoticeType, string> = useMemo(() => ({
      "General": "#e44e72",
      "CompanyEvent": "rgb(44, 201, 114)"
    }), []);

    if (notifications) {
      return (
        <>
          {notifications.length!==0&&(
            <VerticalTimeline animate={false} layout={"1-column-left"}>
              {notifications.map((item, key) => (
                <VerticalTimelineElement
                  contentArrowStyle={{ display: "none" }}
                  contentStyle={{
                    background: "transparent",
                    boxShadow:
                      "0px 4px 8px -2px rgba(16, 24, 40, 0.1), 0px 2px 4px -2px rgba(16, 24, 40, 0.06)",
                    transform: "translateY(-5px)",
                    padding: "15px", // Added padding to the content area
                    borderRadius: "8px", // Rounded corners for a softer look
                  }}
                  onTimelineElementClick={() =>
                    navigate(item.redirect_url ?? `/notices/${item.id}`)
                  }
                  icon={<Icon 
                    type={item.type}
                     />}
                  iconStyle={{
                    // backgroundColor: bgColor[(item.event_type&&item.event_type.includes("Internship")? "Internship":"Placement")||"Update"],
                    backgroundColor: bgColor[item.type],
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    width: "35px", // Set a fixed size for the icon container
                    height: "35px",
                    borderRadius: "50%", // Make the icon container circular
                  }}
                  key={key}
                >
                  <Card
                    className="bg-transparent"
                    style={{
                      cursor: "pointer",
                      overflowX: "hidden",
                      borderRadius: "8px",
                      background: "#fff",
                    }}
                  >
                    <Card.Body className="p-0">
                      <Row>
                        <Col sm={5} className="d-flex align-items-center">
                          <div
                            className="image bg-black rounded-circle d-flex justify-content-center align-items-center"
                            style={{
                              height: "50px",
                              width: "50px",
                              marginRight: "10px",
                              overflow: "hidden",
                            }}
                          >
                            <div
                              className="text-logo"
                              style={{
                                color: "white",
                                fontSize: "1.8rem",
                                fontWeight: "bolder",
                              }}
                            >

                              {
                                !item.company ? "N" :
                                  item.company?.split(" ").length > 1
                                    ? item.company?.split(" ")[0].substring(0, 1)+
                                    item.company?.split(" ")[1].substring(0, 1)
                                    :item.company?.split(" ")[0].substring(0, 1)
                              }
                            </div>
                          </div>
                          <div className="d-flex flex-column">
                            <h5 style={{ margin: "0", fontSize: "1.1rem" }}>
                              {item.title}
                            </h5>
                            <h6 style={{ color: "#6f7274", marginTop: "4px" }}>
                              {item.company}
                            </h6>
                          </div>
                        </Col>
                        <Col
                          sm={7}
                          className="d-flex flex-column align-items-start"
                        >
                          <div style={{maxHeight: "50px", overflow: "hidden", textOverflow: "ellipsis"}}>
                            <HtmlText content={item.content ?? ""} small={false} singleLine={true}/>
                          </div>

                          <div className="d-flex w-100 justify-content-between mt-2">
                            <p
                              style={{
                                margin: "0px",
                                fontWeight: "700",
                                fontSize: "0.9rem",
                              }}
                            >
                              {new Date(item.published_at ?? Date.now()).toString().slice(0, 15)}
                              ,{" "}
                              {new Date(item.published_at ?? Date.now())
                                .toString()
                                .slice(16, 21)}
                            </p>
                            <div className="d-flex gap-2">
                              {item.tag && item.tag.trim().length > 0 && <AnnouncementTagBadge type={item.tag} />}
                            </div>
                          </div>
                        </Col>
                      </Row>
                    </Card.Body>
                  </Card>
                </VerticalTimelineElement>
              ))}
              {showMoreButton&&(
                <ShowMoreButton showMoreButton={showMoreButton} notifications={notifications} fetchNotifications={fetchNotifications} />
              )}
            </VerticalTimeline>
          )}
        </>
      );
    }
}

function ShowMoreButton({showMoreButton, notifications, fetchNotifications}: {showMoreButton: boolean, notifications: any, fetchNotifications: any}) {
  return <>
  {showMoreButton &&
      (<div className="d-flex justify-content-center mb-4">
        <Button
          className="view_more"
          variant="dark"
          disabled={notifications.loading}
          onClick={fetchNotifications}
        >
          {notifications.loading? <Loader />:"View More"}
        </Button>
      </div>)}
  </>
}


export default NoticeThreadUI; 