import React, { useCallback, useMemo, useRef } from 'react';
import ReactQuill, { Quill } from 'react-quill';
// @ts-ignore
import DOMPurify from 'dompurify';
import 'react-quill/dist/quill.snow.css';
import './HtmlText.css';

var Block = Quill.import('blots/block');
Block.tagName = 'DIV';
Quill.register(Block, true);

const HtmlText = ({content, small=false, singleLine=false} : {content: string | object, small?: boolean, singleLine?: boolean})=>{
  // Function to detect if content is Quill Delta format
  const isQuillDelta = useCallback((content: string | object): boolean => {
    if (typeof content === 'object' && Array.isArray(content)) {
      return content.some(item => 
        typeof item === 'object' && 
        (item.insert !== undefined || item.attributes !== undefined)
      );
    }
    if (typeof content === 'string') {
      try {
        const parsed = JSON.parse(content);
        return Array.isArray(parsed) && parsed.some(item => 
          typeof item === 'object' && 
          (item.insert !== undefined || item.attributes !== undefined)
        );
      } catch {
        return false;
      }
    }
    return false;
  }, [content]);

  // Function to detect if content is HTML
  const isHtml = useCallback((content: string | object): boolean => {
    if (typeof content === 'string') {
      return content.includes('<') && content.includes('>');
    }
    return false;
  }, [content]);

  // Process content based on its format
  const getProcessedContent = useCallback(() => {
    if (isQuillDelta(content)) {
      // Handle Quill Delta format
      const delta = typeof content === 'string' ? JSON.parse(content) : content;
      return { type: 'delta', value: delta };
    } else if (isHtml(content)) {
      // Handle HTML format
      return { type: 'html', value: content as string };
    } else {
      // Fallback to treating as plain text
      return { type: 'text', value: content as string };
    }
  }, [content]);

  const processedContent = useMemo(() => getProcessedContent(), [content]);

  // Configuration for ReactQuill to support tables and other formats
  const modules = useMemo(() => ({
    toolbar: false, // No toolbar since it's read-only
  }), []);

  const formats = [
    'header', 'font', 'size',
    'bold', 'italic', 'underline', 'strike', 'blockquote',
    'list', 'bullet', 'indent',
    'link', 'image', 'video',
    'color', 'background',
    'align', 'script', 'code-block'
  ];

  // Render based on content type
  if (processedContent.type === 'html') {
    // For HTML content (including tables), sanitize and use dangerouslySetInnerHTML
    const sanitizedHtml = DOMPurify.sanitize(processedContent.value as string, {
      ADD_TAGS: [
        'table', 'thead', 'tbody', 'tr', 'th', 'td',
        'blockquote', 'cite', 'q',
        'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
        'p', 'br', 'hr',
        'strong', 'b', 'em', 'i', 'u', 'mark', 'del', 'ins',
        'ul', 'ol', 'li',
        'a', 'img',
        'code', 'pre',
        'sub', 'sup'
      ],
      ADD_ATTR: ['colspan', 'rowspan', 'style', 'href', 'src', 'alt', 'title', 'cite']
    });

    return (
      <div 
        className={`html-content-wrapper ${small ? 'small' : ''} ${singleLine ? 'single-line' : ''}`}
        dangerouslySetInnerHTML={{ 
          __html: (singleLine && sanitizedHtml.startsWith("<table>")) ? "Click to read more" : sanitizedHtml 
        }}
      />
    );
  } else {
    // For Quill Delta or plain text, use ReactQuill
    return (
      <div className={`quill-wrapper ${small ? 'small' : ''} ${singleLine ? 'single-line' : ''}`}>
        <ReactQuill 
          value={processedContent.value} 
          readOnly={true}
          modules={modules}
          formats={formats}
          theme="snow"
        />
      </div>
    );
  }
}

export default HtmlText;